<?php
require_once __DIR__.'/../includes/bootstrap.php';
$admin=lh_require_admin();$courses=[];$cats=[];try{$cats=$db->query('SELECT id,name FROM learning_categories WHERE enabled=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$courses=$db->query("SELECT c.*,lc.name category_name FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id ORDER BY c.id DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');try{if($action==='course'){ $title=trim((string)$_POST['title']);$slug=trim((string)$_POST['slug']);$desc=trim((string)$_POST['description']);$cat=(int)$_POST['category_id'];$level=trim((string)$_POST['level']);if($title===''||$slug==='')throw new RuntimeException('Title and slug required.');$q=$db->prepare('INSERT INTO learning_courses(title,slug,description,category_id,level,featured,enabled) VALUES(?,?,?,?,?,?,1)');$q->execute([$title,$slug,$desc,$cat,$level,!empty($_POST['featured'])?1:0]);}elseif($action==='lesson'){ $course=(int)$_POST['course_id'];$title=trim((string)$_POST['title']);$slug=trim((string)$_POST['slug']);$content=(string)$_POST['content'];$order=(int)$_POST['sort_order'];$q=$db->prepare('INSERT INTO learning_lessons(course_id,title,slug,content,sort_order,enabled) VALUES(?,?,?,?,?,1)');$q->execute([$course,$title,$slug,$content,$order]);}header('Location:/learning-hub/admin/');exit;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learning Admin</title><style>body{margin:0;font-family:Inter,Arial;background:#f6f8fc;color:#172033}.wrap{width:min(1100px,calc(100% - 28px));margin:auto;padding:35px 0}.card{background:#fff;border:1px solid #e5e8ef;border-radius:18px;padding:22px;margin-bottom:18px}h1{margin-top:0}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.full{grid-column:1/-1}label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}input,select,textarea{width:100%;padding:11px;border:1px solid #dfe4ec;border-radius:10px;box-sizing:border-box;font:inherit}textarea{min-height:150px}.btn{background:#635bff;color:#fff;border:0;padding:11px 16px;border-radius:10px;font-weight:800}.table{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #eee;font-size:13px}.error{background:#fff0ef;color:#b42318;padding:10px;border-radius:10px;margin-bottom:15px}@media(max-width:700px){.form{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><main class="wrap"><h1>🎓 Learning Hub Admin</h1><p>Signed in as <?=lh_h($admin['email']??'admin')?></p><?php if(!empty($error)):?><div class="error"><?=lh_h($error)?></div><?php endif;?><section class="card"><h2>Create course</h2><form method="post" class="form"><input type="hidden" name="action" value="course"><div><label>Title</label><input name="title" required></div><div><label>Slug</label><input name="slug" placeholder="learn-php" required></div><div><label>Category</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=lh_h($c['id'])?>"><?=lh_h($c['name'])?></option><?php endforeach;?></select></div><div><label>Level</label><select name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div class="full"><label>Description</label><textarea name="description"></textarea></div><div><label><input type="checkbox" name="featured" value="1"> Featured</label></div><div class="full"><button class="btn">Create course</button></div></form></section><section class="card"><h2>Add lesson</h2><form method="post" class="form"><input type="hidden" name="action" value="lesson"><div><label>Course</label><select name="course_id"><?php foreach($courses as $c):?><option value="<?=lh_h($c['id'])?>"><?=lh_h($c['title'])?></option><?php endforeach;?></select></div><div><label>Lesson title</label><input name="title" required></div><div><label>Lesson slug</label><input name="slug" required></div><div><label>Order</label><input type="number" name="sort_order" value="0"></div><div class="full"><label>Content</label><textarea name="content"></textarea></div><div class="full"><button class="btn">Add lesson</button></div></form></section><section class="card"><h2>Courses</h2><div class="table"><table><tr><th>ID</th><th>Course</th><th>Category</th><th>Level</th><th>Status</th></tr><?php foreach($courses as $c):?><tr><td><?=lh_h($c['id'])?></td><td><b><?=lh_h($c['title'])?></b><br><small><?=lh_h($c['slug'])?></small></td><td><?=lh_h($c['category_name']??'—')?></td><td><?=lh_h($c['level'])?></td><td><?=!empty($c['enabled'])?'Published':'Off'?></td></tr><?php endforeach;?></table></div></section></main></body></html>
